#!/usr/bin/env python3
"""Parcours complet d'un patient, comme un utilisateur (v3) :
  A. patient → histoire clinique → bilans → phase 1 (crises saisies) → capture de tracé collée (Ctrl+V) et annotée →
     staff (préparer : question, hypothèse du modèle, décision SEEG, capture à montrer ; présenter : diaporama, « Revoir »
     une crise puis retour) ;
  v4.21 : Imagerie en trois colonnes (catégories), dossier DICOM synthétique converti, repères et poignées d'ajustement
     du recalage (glisser réel), modèles d'électrodes DIXI / Alcis, encart cliquable, MIP du scanner ;
  B. SEEG : T1 + scanner post-implantation (synthétiques), import de la planification chirurgicale (CSV), localisation
     (détection, correspondance avec le schéma, vérification une à une), crise SEEG (plots de début), stimulation
     (la coupe suit l'électrode), thermocoagulation, rapport SEEG, staff après SEEG présenté ;
  C. suppression du patient : toutes ses données disparaissent.
    python tools/tests/test_flow_v3.py [T1.nii.gz CT.nii.gz truth.json] [dossier_captures]
Images synthétiques (tools/tests/make_synth_ct.py) ; captures dans un dossier temporaire local."""
import os, sys, json, re, tempfile, time, base64, struct, zlib, glob, subprocess, atexit, shutil
from playwright.sync_api import sync_playwright
