T1, CT, TRUTH = A[0:3] if len(A) >= 3 else ['/tmp/claude-0/data/sub01_T1_3D_20260301.nii.gz', '/tmp/claude-0/data/sub01_CT_postimplant_20260603.nii.gz', '/tmp/claude-0/ct/truth.json']
OUT = A[3] if len(A) > 3 else os.environ.get('EPI_SHOTS') or '/tmp/claude-0/flow3'; os.makedirs(OUT, exist_ok=True)
SKIP_B = os.environ.get('FLOW_SKIP_B') == '1'
errs, fails, confirms = [], [], []
def redraw(pg, t):
    """page du tracé à t s, puis attendre qu’elle soit peinte (dessin différé à l’image suivante)"""
    pg.evaluate("t=>{ const V=SV.app._iev; V.heatN=-1; V.t=t; SV.app.ieegDraw(); }", t)
    pg.wait_for_function("()=>SV.app._iev.heatN>=0", timeout=15_000); pg.wait_for_timeout(100)

def check(cond, msg):
    print(('ok   ' if cond else 'ÉCHEC ') + msg, flush=True)
    if not cond: fails.append(msg)
def shot(pg, name): pg.screenshot(path=os.path.join(OUT, name + '.png'), timeout=120_000)
def png_bytes(w=320, h=120):
    """PNG synthétique (tracé : sinusoïdes) pour la galerie"""
    import math
    rows = []
    for y in range(h):
        row = bytearray([0])
        for x in range(w):
            on = any(abs(y - (20 + 25 * k + 8 * math.sin(x / (6 + 3 * k)))) < 1.2 for k in range(4))
            row += bytes([20, 20, 20]) if on else bytes([250, 250, 250])
        rows.append(bytes(row))
    raw = b''.join(rows)
    def chunk(t, d): c = struct.pack('>I', len(d)) + t + d; return c + struct.pack('>I', zlib.crc32(t + d) & 0xffffffff)
    return b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 2, 0, 0, 0)) + chunk(b'IDAT', zlib.compress(raw)) + chunk(b'IEND', b'')
PNG64 = base64.b64encode(png_bytes()).decode()
PASTE = """b64 => { const bin = atob(b64), a = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
  const dt = new DataTransfer(); dt.items.add(new File([a], 'capture.png', { type: 'image/png' }));
  document.dispatchEvent(new ClipboardEvent('paste', { clipboardData: dt, bubbles: true })); }"""

prompts = ['FLOW-01']

