        check(fc['n'] >= 1 and fc['rows'] >= 1 and fc['top'][2] == 1 and fcq and fcq['nr'] == fc['n'] and fcq['paint'] == fcq['nr'] and fcq['top'] >= 1 and fcq['nv'] >= 10, f'v4.20 : empreinte connectivité — régions candidates (échantillonnées ou non : {fc["unsampled"]} non échantillonnées), jeu « Empreinte connectivité » peint par région en 3D ({fc}, {fcq})')
